"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[377],{60015:e=>{e.exports=JSON.parse('{"tag":{"label":"Foundation Models & LLMs","permalink":"/science/tags/foundation-models-ll-ms","allTagsPath":"/science/tags","count":6,"items":[{"id":"2024/llm-generation","title":"Code Generation and Documentation Search using Large Language Model","description":"Author: Aldo Malaquias Cabrera, Summer 2024","permalink":"/science/2024/llm-generation"},{"id":"2024/finding-events","title":"Creating a System to Find Events in Real Time","description":"Across the United States and the world, the distributed network of Sage nodes captures over 2500 images per day. These nodes have the potential of capturing photos with important features such as smoke, wildlife, and emergencies. Each image contains unique characteristics which, until now, were hard to look for without manually searching through the Sage database. With both the images and users in mind, this project has two goals: harness the power of machine learning to describe photos as they are taken, and build a user-friendly system to allow others to find what they are looking for within our database.","permalink":"/science/2024/finding-events"},{"id":"2026/bisonn","title":"Exploring the Potential for Edge Computing to Collect Novel Biotic Interaction Data","description":"Kyle Lima","permalink":"/science/2026/bisonn"},{"id":"2026/image-search-at-the-edge","title":"Image Search at the Edge","description":"Authors: Sajan Neupane (University of Utah) and Pratik Kharade (University of Utah \u2013 SCI Institute)","permalink":"/science/2026/image-search-at-the-edge"},{"id":"2026/manoomin-vision","title":"Manoomin Vision","description":"Authors: Jordan Gurneau (Northwestern University), Ella Neumann (Georgia Tech / MIT), Dave MacDonald (UC Davis), Deanna DiMonte (Northwestern University), and Morty (lead)","permalink":"/science/2026/manoomin-vision"},{"id":"2026/ndp-scidx-mcp","title":"Sage-NDP-SciDx MCP","description":"Authors: Pratik Kharade (University of Utah \u2013 SCI Institute) and Sajan Neupane (University of Utah)","permalink":"/science/2026/ndp-scidx-mcp"}],"unlisted":false}}')}}]);